package com.zzy.ksongfloat.ai; public class AiCallResult { public final boolean success; public final AiResponse response; public final AiError error; public final AiRequestState state; public AiCallResult(boolean s,AiResponse r,AiError e,AiRequestState st){success=s;response=r;error=e;state=st;} public static AiCallResult ok(AiResponse r){return new AiCallResult(true,r,null,AiRequestState.SUCCESS);} public static AiCallResult fail(AiError e){return new AiCallResult(false,null,e,AiRequestState.FAILED);} }
